CREATE TABLE profiles (id VARCHAR(64) PRIMARY KEY, revision INTEGER NOT NULL, body CLOB NOT NULL);
CREATE TABLE profile_revisions (profile_id VARCHAR(64) NOT NULL, revision INTEGER NOT NULL, body CLOB NOT NULL, PRIMARY KEY(profile_id, revision));
CREATE TABLE plans (id VARCHAR(64) PRIMARY KEY, body CLOB NOT NULL);
CREATE TABLE runs (id VARCHAR(64) PRIMARY KEY, plan_id VARCHAR(64) NOT NULL REFERENCES plans(id), environment VARCHAR(100) NOT NULL, state VARCHAR(40) NOT NULL, body CLOB NOT NULL);
CREATE TABLE submissions (idempotency_key VARCHAR(128) PRIMARY KEY, request_hash VARCHAR(64) NOT NULL, run_id VARCHAR(64) NOT NULL REFERENCES runs(id));
CREATE TABLE events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id VARCHAR(64) NOT NULL REFERENCES runs(id), event_time VARCHAR(40) NOT NULL, state VARCHAR(40) NOT NULL, message VARCHAR(2000) NOT NULL);
CREATE INDEX events_by_run ON events(run_id, id);
CREATE TABLE environment_leases (scope VARCHAR(250) PRIMARY KEY, run_id VARCHAR(64) NOT NULL REFERENCES runs(id), owner VARCHAR(64) NOT NULL, fencing_token BIGINT NOT NULL, renewed_at VARCHAR(40) NOT NULL, expires_at VARCHAR(40) NOT NULL);
CREATE TABLE coordination (id INTEGER PRIMARY KEY);
INSERT INTO coordination VALUES (1);
CREATE TABLE simulated_deployments (scope VARCHAR(300) PRIMARY KEY, digest VARCHAR(100) NOT NULL, operation_id VARCHAR(150) NOT NULL);
CREATE TABLE simulated_loads (run_id VARCHAR(64) PRIMARY KEY REFERENCES runs(id), operation_id VARCHAR(150) NOT NULL, state VARCHAR(30) NOT NULL);
CREATE TABLE audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor VARCHAR(100) NOT NULL, action VARCHAR(100) NOT NULL, target VARCHAR(200) NOT NULL, occurred_at VARCHAR(40) NOT NULL);
